  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C32"],
      "claim": "LCB01-0371 (delpazolid) had an absolute oral bioavailability of 99.75% after an 800 mg oral dose versus IV in healthy volunteers, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Pethidine (meperidine) had an absolute oral bioavailability of 0.52 (52%) after oral administration in healthy subjects, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Meptazinol had a mean absolute oral bioavailability of 8.7 ± 1.6% after a 200 mg oral dose versus IV in healthy young male volunteers, supporting F < 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most high-transfer evidence molecules show absolute oral bioavailability at or above 20%, including values of 99.75%, 80.5%, ~52%, and ~90%, while two high-transfer molecules (meptazinol ~8.7%, pentazocine ~18%) fall below the threshold. Overall, high is better supported, but the conflicting low-F evidence lowers confidence.",
  "evidence_gaps": [
    "Two high-transfer molecules provide affirmative low-F evidence, conflicting with the majority of high-transfer molecules supporting high F.",
    "Some positive evidence is qualitative or model-based, reducing directness for those records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

